            raise TypeError("Input must be a string")

        textnum = textnum.lower().strip()

        if not textnum:
            raise ValueError("Input cannot be empty")

        # Replace hyphens with spaces for processing
        textnum = textnum.replace('-', ' ')

        # Split into words
        words = textnum.split()

        # Check for ordinal numbers and convert to cardinal
        if words[-1] in self.ordinal_words:
            words[-1] = str(self.ordinal_words[words[-1]])
            return "".join(words)

        # Check for ordinal endings
        for ending, replacement in self.ordinal_endings:
            if words[-1].endswith(ending):
                cardinal_word = words[-1][:-len(ending)] + replacement
                if cardinal_word in self.numwords:
